const getTrialBalanceByChartAccount = `-- name: GetTrialBalanceByChartAccount :many

SELECT
    ca.id AS chart_account_id,
    ca.code,
    ca.name,
    ca.account_class,
    ca.subtype,
    ca.is_control,
    COALESCE(SUM(CASE WHEN le.entry_date < $2::date THEN ll.debit_minor ELSE 0 END), 0)::bigint AS opening_debit_minor,
    COALESCE(SUM(CASE WHEN le.entry_date < $2::date THEN ll.credit_minor ELSE 0 END), 0)::bigint AS opening_credit_minor,
    COALESCE(SUM(CASE WHEN le.entry_date >= $2::date AND le.entry_date <= $3::date THEN ll.debit_minor ELSE 0 END), 0)::bigint AS period_debit_minor,
    COALESCE(SUM(CASE WHEN le.entry_date >= $2::date AND le.entry_date <= $3::date THEN ll.credit_minor ELSE 0 END), 0)::bigint AS period_credit_minor,
    COALESCE(SUM(CASE WHEN le.entry_date <= $3::date THEN ll.debit_minor ELSE 0 END), 0)::bigint AS closing_debit_minor,
    COALESCE(SUM(CASE WHEN le.entry_date <= $3::date THEN ll.credit_minor ELSE 0 END), 0)::bigint AS closing_credit_minor
FROM chart_accounts ca
LEFT JOIN ledger_lines ll ON ll.chart_account_id = ca.id AND ll.workspace_id = ca.workspace_id
LEFT JOIN ledger_entries le ON le.id = ll.ledger_entry_id AND le.workspace_id = ll.workspace_id AND le.currency = $4::text
WHERE ca.workspace_id = $1
GROUP BY ca.id, ca.code, ca.name, ca.account_class, ca.subtype, ca.is_control
ORDER BY ca.code ASC
`

