const listJournalsCursor = `-- name: ListJournalsCursor :many
SELECT le.id, le.workspace_id, le.source_type, le.source_id, le.entry_date, le.currency, le.currency_exponent, le.description, le.is_reversed, le.reversed_by_entry_id, le.created_at, le.template_key, le.template_version, le.status, le.reversal_of_entry_id, le.accounting_period_id, le.outlet_id, le.posted_by_user_id, le.idempotency_key
FROM ledger_entries le
WHERE le.workspace_id = $1
  AND ($3::date IS NULL OR le.entry_date >= $3)
  AND ($4::date IS NULL OR le.entry_date <= $4)
  AND ($5::text IS NULL OR le.source_type = $5)
  AND ($6::bigint IS NULL OR le.accounting_period_id = $6)
  AND ($7::bigint IS NULL OR le.outlet_id = $7)
  AND (
      $8::bigint IS NULL
      OR EXISTS (
          SELECT 1 FROM ledger_lines ll
          WHERE ll.ledger_entry_id = le.id AND ll.workspace_id = le.workspace_id AND ll.chart_account_id = $8
      )
  )
  AND (
      $9::date IS NULL
      OR (le.entry_date, le.id) < ($9::date, $10::bigint)
  )
ORDER BY le.entry_date DESC, le.id DESC
LIMIT $2
`

